func TestImportFromAntigravity_RulesAndAgents(t *testing.T) {
	dir := t.TempDir()
	rulesDir := filepath.Join(dir, ".agent", "rules")
	if err := os.MkdirAll(rulesDir, 0o755); err != nil {
		t.Fatal(err)
	}
	writeFile(t, filepath.Join(rulesDir, "go-style.md"),
		"<!-- Generated by agnostic-ai. Do not edit. -->\n\n# go-style\n\ngofmt clean.\n")
	writeFile(t, filepath.Join(rulesDir, "agent-helper.md"),
		"<!-- Generated by agnostic-ai. Do not edit. -->\n\n# Agent: helper\n\nhelper body.\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}

	ruleData, err := os.ReadFile(filepath.Join(dir, "rules", "go-style.md"))
	if err != nil {
		t.Fatalf("missing rules/go-style.md: %v", err)
	}
	if !strings.Contains(string(ruleData), "name: go-style") {
		t.Errorf("expected name: go-style frontmatter, got %s", ruleData)
	}
	if !strings.Contains(string(ruleData), "gofmt clean.") {
		t.Errorf("expected rule body, got %s", ruleData)
	}
	if strings.Contains(string(ruleData), "Generated by agnostic-ai") {
		t.Errorf("provenance header not stripped: %s", ruleData)
	}

	agentData, err := os.ReadFile(filepath.Join(dir, "agents", "helper.md"))
	if err != nil {
		t.Fatalf("missing agents/helper.md: %v", err)
	}
	if !strings.Contains(string(agentData), "name: helper") {
		t.Errorf("expected name: helper frontmatter, got %s", agentData)
	}
	if !strings.Contains(string(agentData), "helper body.") {
		t.Errorf("expected agent body, got %s", agentData)
	}
}

// TestImportFromAntigravity_ReadsPluralRulesDir is the round-trip half
// of the paths fix: sync now defaults to `.agents/rules`, so import
// must read from there too, not just the legacy `.agent/rules`.
func TestImportFromAntigravity_ReadsPluralRulesDir(t *testing.T) {
	dir := t.TempDir()
	rulesDir := filepath.Join(dir, ".agents", "rules")
	if err := os.MkdirAll(rulesDir, 0o755); err != nil {
		t.Fatal(err)
	}
	writeFile(t, filepath.Join(rulesDir, "go-style.md"),
		"<!-- Generated by agnostic-ai. Do not edit. -->\n\n# go-style\n\ngofmt clean.\n")
	writeFile(t, filepath.Join(rulesDir, "agent-helper.md"),
		"<!-- Generated by agnostic-ai. Do not edit. -->\n\n# Agent: helper\n\nhelper body.\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}

	ruleData, err := os.ReadFile(filepath.Join(dir, "rules", "go-style.md"))
	if err != nil {
		t.Fatalf("missing rules/go-style.md: %v", err)
	}
	if !strings.Contains(string(ruleData), "gofmt clean.") {
		t.Errorf("expected rule body, got %s", ruleData)
	}
	if _, err := os.Stat(filepath.Join(dir, "agents", "helper.md")); err != nil {
		t.Errorf("missing agents/helper.md: %v", err)
	}
}

// TestImportFromAntigravity_ReadsScopedRulesDirs is the import half of
// the scoped-rules fix: sync writes a scoped rule to
// `<scope>/.agents/rules/<name>.md`, outside the project's own rules
// tree, so import has to scan the project for that layout too (#1114).
func TestImportFromAntigravity_ReadsScopedRulesDirs(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, ".agents", "rules", "root.md"), "# root\n\nroot body\n")
	writeFile(t, filepath.Join(dir, "backend", ".agents", "rules", "auth.md"), "# auth\n\nauth body\n")
	writeFile(t, filepath.Join(dir, "backend", "api", ".agents", "rules", "limits.md"), "# limits\n\nlimits body\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}

	for _, p := range []string{
		filepath.Join("rules", "root.md"),
		filepath.Join("rules", "backend", "auth.md"),
		filepath.Join("rules", "backend", "api", "limits.md"),
	} {
		if _, err := os.Stat(filepath.Join(dir, p)); err != nil {
			t.Errorf("missing imported spec %s: %v", p, err)
		}
	}
}

// TestImportFromAntigravity_ReadsHiddenAndVendorScopedRulesDirs pins
// #1114's import-side fix: `CheckScopePath` accepts a scope like
// `.github`, `vendor`, or `node_modules`, so emission can write a
// scoped rule under any of them, and import must round-trip it instead
// of pruning the directory before ever looking inside it.
func TestImportFromAntigravity_ReadsHiddenAndVendorScopedRulesDirs(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, ".github", ".agents", "rules", "release.md"), "# release\n\nrelease body\n")
	writeFile(t, filepath.Join(dir, "vendor", ".agents", "rules", "pkg.md"), "# pkg\n\npkg body\n")
	writeFile(t, filepath.Join(dir, "node_modules", ".agents", "rules", "pkg2.md"), "# pkg2\n\npkg2 body\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}

	for _, p := range []string{
		filepath.Join("rules", ".github", "release.md"),
		filepath.Join("rules", "vendor", "pkg.md"),
		filepath.Join("rules", "node_modules", "pkg2.md"),
	} {
		if _, err := os.Stat(filepath.Join(dir, p)); err != nil {
			t.Errorf("missing imported spec %s: %v", p, err)
		}
	}
}

// TestImportFromAntigravity_SkipsGitAndOwnOutputDirs confirms the scan
// still prunes `.git` (never a legitimate scope) and Antigravity's own
// output roots (`.agents`, `.agent`), which the non-scoped import call
// already reads; walking into them looking for a nested copy of
// themselves would either find nothing or misread the tool's own tree
// as a scope.
func TestImportFromAntigravity_SkipsGitAndOwnOutputDirs(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, ".git", ".agents", "rules", "ignored.md"), "# ignored\n\nignored body\n")
	writeFile(t, filepath.Join(dir, ".agents", "rules", "root.md"), "# root\n\nroot body\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}

	if _, err := os.Stat(filepath.Join(dir, "rules", "ignored.md")); !os.IsNotExist(err) {
		t.Errorf(".git must never be scanned for scopes, err=%v", err)
	}
	if _, err := os.Stat(filepath.Join(dir, "rules", "root.md")); err != nil {
		t.Errorf("missing imported spec rules/root.md: %v", err)
	}
}

func TestImportFromAntigravity_ImportsNestedAgentProfiles(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, ".agents/agents/reviewer/agent.md"),
		"---\nname: reviewer\ndescription: Reviews changes.\n---\n<!-- Generated by agnostic-ai. Do not edit. -->\nReview the diff.\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(dir, "agents/reviewer.md"))
	if err != nil {
		t.Fatalf("missing imported agent: %v", err)
	}
	if !strings.Contains(string(data), "Review the diff.") || strings.Contains(string(data), "Generated by agnostic-ai") {
		t.Errorf("unexpected imported agent:\n%s", data)
	}
}

func TestImportFromAntigravity_NestedProfilesTakePrecedenceOverFlat(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, ".agents/agents/antigravity/agent.md"), "---\nname: antigravity\n---\nNested.\n")
	writeFile(t, filepath.Join(dir, ".agents/agents/goose.md"), "---\nname: goose\n---\nFlat.\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(dir, "agents/antigravity.md")); err != nil {
		t.Errorf("missing nested agent import: %v", err)
	}
	if _, err := os.Stat(filepath.Join(dir, "agents/goose.md")); !os.IsNotExist(err) {
		t.Errorf("flat shared profile should not be imported when nested profiles exist, err=%v", err)
	}
}

