// The regression this PR fixes (#1117 review): a `manual` rule that
// also carries a `description` (the vendor recommends one on every
// rule) must keep `x-antigravity.trigger: manual` on import. Without
// it, the generic fields alone (`alwaysApply: false` + a description,
// no globs) re-derive as `model_decision` on the next sync, silently
// turning an explicit @-mention-only rule into an automatically-loaded
// one.
func TestImportFromAntigravity_ManualTriggerWithDescriptionPreservesNativeOverride(t *testing.T) {
	dir := t.TempDir()
	rulesDir := filepath.Join(dir, ".agents", "rules")
	if err := os.MkdirAll(rulesDir, 0o755); err != nil {
		t.Fatal(err)
	}
	writeFile(t, filepath.Join(rulesDir, "checklist.md"),
		"---\ntrigger: manual\ndescription: Release checklist, read on demand.\n---\n\n<!-- Generated by agnostic-ai. Do not edit. -->\n\n# checklist\n\nConfirm the changelog.\n")

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(dir, "rules", "checklist.md"))
	if err != nil {
		t.Fatalf("missing rules/checklist.md: %v", err)
	}
	got := string(data)
	for _, want := range []string{"alwaysApply: false", "description: Release checklist, read on demand.", "x-antigravity:", "trigger: manual"} {
		if !strings.Contains(got, want) {
			t.Errorf("expected %q, got: %s", want, got)
		}
	}
}

// An unrecognized trigger value (a hand-edited typo, or a future
// vendor addition agnostic-ai does not know yet) gets no generic
// `alwaysApply` mapping, only the verbatim `x-antigravity.trigger`, and
// a warning, so it never silently re-derives as some default on the
// next sync (#1117 review).
func TestImportFromAntigravity_UnknownTriggerPreservedVerbatimAndWarns(t *testing.T) {
	dir := t.TempDir()
	rulesDir := filepath.Join(dir, ".agents", "rules")
	if err := os.MkdirAll(rulesDir, 0o755); err != nil {
		t.Fatal(err)
	}
	writeFile(t, filepath.Join(rulesDir, "typo.md"),
		"---\ntrigger: alwaysOn\n---\n\n<!-- Generated by agnostic-ai. Do not edit. -->\n\n# typo\n\nUse tabs.\n")

	var buf bytes.Buffer
	prev := logOut
	logOut = &buf
	defer func() { logOut = prev }()

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(buf.String(), `trigger "alwaysOn"`) {
		t.Errorf("expected a warning naming the unrecognized trigger, got: %s", buf.String())
	}

	data, err := os.ReadFile(filepath.Join(dir, "rules", "typo.md"))
	if err != nil {
		t.Fatalf("missing rules/typo.md: %v", err)
	}
	got := string(data)
	if !strings.Contains(got, "x-antigravity:") || !strings.Contains(got, "trigger: alwaysOn") {
		t.Errorf("expected the unrecognized trigger preserved verbatim under x-antigravity, got: %s", got)
	}
	if strings.Contains(got, "alwaysApply:") {
		t.Errorf("an unrecognized trigger must not get a generic alwaysApply mapping, got: %s", got)
	}
}

func TestImportFromAntigravity_MirrorsAgentsMD(t *testing.T) {
	dir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(dir, ".agents"), 0o755); err != nil {
		t.Fatal(err)
	}
	body := "# Project\n\nTop-level instructions.\n"
	writeFile(t, filepath.Join(dir, ".agents", "AGENTS.md"), body)

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(filepath.Join(dir, agnosticMainFile))
	if err != nil {
		t.Fatalf("missing %s: %v", agnosticMainFile, err)
	}
	if string(got) != body {
		t.Errorf("%s not byte-identical to .agents/AGENTS.md. got %q", agnosticMainFile, got)
	}
}

// A project synced before #1114 only has the legacy `.agent/AGENTS.md`.
// Import falls back to it when the preferred `.agents/AGENTS.md` is
// absent.
func TestImportFromAntigravity_MirrorsLegacyAgentsMD(t *testing.T) {
	dir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(dir, ".agent"), 0o755); err != nil {
		t.Fatal(err)
	}
	body := "# Project\n\nLegacy top-level instructions.\n"
	writeFile(t, filepath.Join(dir, ".agent", "AGENTS.md"), body)

	if err := importFromAntigravity(dir, rootSources(), nil); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(filepath.Join(dir, agnosticMainFile))
	if err != nil {
		t.Fatalf("missing %s: %v", agnosticMainFile, err)
	}
	if string(got) != body {
		t.Errorf("%s not byte-identical to .agent/AGENTS.md. got %q", agnosticMainFile, got)
	}
}
